using Majorsilence.Reporting.Data;
using NUnit.Framework;
using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Text;

namespace ReportTests
{
    /// <summary>
    /// Pins the tables JsonTableExtractor produces for a range of document shapes. The expected text was
    /// generated by the original dictionary based implementation, so the array based one must match it.
    /// </summary>
    [TestFixture]
    public class JsonExtractorShapeTests
    {
        public static readonly (string Name, string Json)[] Documents =
        [
            ("flat", """[{"Id":1,"Name":"a","Price":1.5,"Ok":true},{"Id":2,"Name":"b","Price":2,"Ok":false}]"""),
            ("varying-keys", """[{"a":1,"b":2},{"b":3,"c":4},{"a":5}]"""),
            ("first-row-nulls", """[{"a":null,"b":"x"},{"a":7,"b":null}]"""),
            ("object-root", """{"Id":1,"Name":"solo","Tags":["x","y"],"Inner":{"k":1,"deep":{"z":2}}}"""),
            ("nested", """[{"Id":1,"Kids":[{"N":"a"},{"N":"b"}],"Info":{"Phone":"1","Email":"e"}},{"Id":2,"Kids":[],"Info":{"Phone":"2","Email":"f"}}]"""),
            ("primitive-array", """[{"Id":1,"Tags":["x","y","z"]},{"Id":2,"Tags":["w"]}]"""),
            ("empty-array", "[]"),
            ("deep", """[{"A":{"B":{"C":{"D":1}}},"L":[{"M":[{"O":1},{"O":2}]}]}]"""),
            ("name-clash", """[{"a":{"b":1},"a_b":2}]"""),
            ("numbers", """[{"i":1,"l":9999999999,"d":1.25,"e":1e3,"n":-0.5}]"""),
            ("unicode", """[{"s":"héllo 😀","t":"tab\there"}]"""),
            ("array-of-arrays", """[[1,2]]"""),
            ("primitive-root", "42"),
            ("trailing-content", """[{"a":1}] x"""),
            ("truncated", """[{"a":1},"""),
            ("array-of-primitives", """[1,2,3]"""),
        ];

        /// <summary>Normalises guids (they are random) to g1, g2, ... in order of first appearance.</summary>
        public static string Dump(string json)
        {
            var sb = new StringBuilder();
            Dictionary<string, IDataReader> tables;
            try
            {
                tables = new JsonTableExtractor().Extract(json);
            }
            catch (Exception e)
            {
                return "EXCEPTION " + e.GetType().Name;
            }

            var guids = new Dictionary<string, string>();
            string Fmt(object v)
            {
                if (v == null || v == DBNull.Value) return "NULL";
                if (v is Dictionary<string, object> d)
                    return "{" + string.Join(",", d.Select(kv => kv.Key + "=" + Fmt(kv.Value))) + "}";
                if (v is string s && Guid.TryParse(s, out _))
                {
                    if (!guids.TryGetValue(s, out var g)) guids[s] = g = "g" + (guids.Count + 1);
                    return "guid:" + g;
                }
                return v.GetType().Name + ":" + System.Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture);
            }

            foreach (var name in tables.Keys.OrderBy(k => k, StringComparer.Ordinal))
            {
                var dr = tables[name];
                sb.Append("table ").Append(name).Append(" cols=");
                sb.Append(string.Join(",", Enumerable.Range(0, dr.FieldCount).Select(i => dr.GetName(i) + ":" + dr.GetFieldType(i).Name)));
                sb.AppendLine();
                while (dr.Read())
                {
                    var vals = new object[dr.FieldCount];
                    dr.GetValues(vals);
                    sb.Append("  ").AppendLine(string.Join(" | ", vals.Select(Fmt)));
                }
            }

            return sb.ToString();
        }

        [Test]
        public void Tables_MatchTheOriginalImplementation()
        {
            string dumpTo = Environment.GetEnvironmentVariable("JSON_GOLDEN_OUT");
            var all = new StringBuilder();
            foreach (var (name, json) in Documents)
                all.Append("### ").AppendLine(name).Append(Dump(json)).AppendLine();

            if (!string.IsNullOrEmpty(dumpTo))
            {
                System.IO.File.WriteAllText(dumpTo, all.ToString());
                Assert.Pass("golden written");
            }

            Assert.That(all.ToString().Replace("\r\n", "\n").TrimEnd(), Is.EqualTo(JsonExtractorGolden.Text.Replace("\r\n", "\n").TrimEnd()));
        }

        [Test]
        public void Extract_SkipsUtf8ByteOrderMark()
        {
            byte[] bytes = new byte[] { 0xEF, 0xBB, 0xBF }.Concat(Encoding.UTF8.GetBytes("""[{"a":1}]""")).ToArray();
            var tables = new JsonTableExtractor().Extract(bytes);
            Assert.That(tables["root"].Read(), Is.True);
        }

        [TestCase("UTF-16")]
        [TestCase("utf-16BE")]
        [TestCase("utf-32")]
        public void Extract_DecodesOtherEncodingsFromTheirByteOrderMark(string encodingName)
        {
            var enc = Encoding.GetEncoding(encodingName);
            byte[] bytes = enc.GetPreamble().Concat(enc.GetBytes("""[{"a":"é"}]""")).ToArray();
            var dr = new JsonTableExtractor().Extract(bytes)["root"];
            Assert.That(dr.Read(), Is.True);
            Assert.That(dr.GetValue(dr.GetOrdinal("a")), Is.EqualTo("é"));
        }
    }
}
